		SPARK_FAIL(SPARK_STATUS_CAPACITY_EXCEEDED);
	draft->tokens = (uint32_t *)malloc((size_t)lane_count * lane_capacity * sizeof(uint32_t));
	draft->lengths = (uint32_t *)calloc(lane_count,sizeof(uint32_t));
