		 SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_HIDDEN_TRANSPORT);
	if ( transport_set ==
			(SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_PARALLEL_FANOUT |
			 SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_HIDDEN_TRANSPORT) &&
		(descriptor->capability_flags &
		 SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_HYBRID_TP_PP) == 0u )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( (descriptor->capability_flags &
			SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_HYBRID_TP_PP) != 0u &&
		transport_set !=
			(SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_PARALLEL_FANOUT |
			 SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_HIDDEN_TRANSPORT) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkDescriptorCheckBoundaryAndCodecFields(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	if ( descriptor->boundary_format != SPARK_MODEL_SERVING_BOUNDARY_FORMAT_BF16 || descriptor->boundary_element_count == 0u || descriptor->boundary_element_bytes != sizeof(uint16_t) || SparkWeightCodecIsKnown(descriptor->linear_weight_codec) == 0u || SparkWeightCodecIsKnown(descriptor->expert_weight_codec) == 0u || SparkWeightCodecIsKnown(descriptor->kv_cache_codec) == 0u )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkDescriptorCheckCapacityFields(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	if ( descriptor->max_inflight_submission_count == 0u || descriptor->max_inflight_submission_count > SPARK_MODEL_SERVING_ADAPTER_MAX_INFLIGHT_SUBMISSION_COUNT || descriptor->max_active_sequence_count == 0u || descriptor->max_active_sequence_count > SPARK_MODEL_SERVING_ADAPTER_MAX_ACTIVE_SEQUENCE_COUNT || descriptor->max_input_row_count < descriptor->max_active_sequence_count || descriptor->max_input_row_count > SPARK_MODEL_SERVING_ADAPTER_MAX_INPUT_ROW_COUNT || descriptor->max_resident_sequence_count < descriptor->max_active_sequence_count || descriptor->max_resident_sequence_count > SPARK_MODEL_SERVING_ADAPTER_MAX_RESIDENT_SEQUENCE_COUNT || descriptor->max_output_token_count == 0u || descriptor->max_output_token_count > SPARK_MODEL_SERVING_ADAPTER_MAX_OUTPUT_TOKEN_COUNT )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkDescriptorCheckSpeculationPairing(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	if ( ((descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_SPECULATION) != 0u) != (descriptor->max_speculative_token_count != 0u) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( (descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_SPECULATIVE_VERIFY) != 0u &&
		((descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_SPECULATION) == 0u ||
		 descriptor->max_speculative_token_count + 1u > SPARK_MODEL_SERVING_ADAPTER_MAX_VERIFY_TOKENS_PER_SEQUENCE ||
		 descriptor->max_verify_row_count < descriptor->max_speculative_token_count + 1u ||
		 descriptor->max_verify_row_count > descriptor->max_input_row_count) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( (descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_SPECULATIVE_VERIFY) == 0u && descriptor->max_verify_row_count != 0u )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkDescriptorCheckDecodeChainRequirements(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	if ( (descriptor->capability_flags &
		SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_RESIDENT_DECODE_CHAIN) != 0u &&
		(descriptor->capability_flags &
		 SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_CONTINUE_LEASE) == 0u )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( (descriptor->capability_flags &
		SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_RESIDENT_DECODE_CHAIN) != 0u &&
		descriptor->max_output_token_count < 2u )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( descriptor->minimum_efficient_submission_row_count > descriptor->max_input_row_count )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkDescriptorCheckCacheBlockFields(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	uint32_t hybrid;
	hybrid = (descriptor->capability_flags &
		SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_HYBRID_TP_PP) != 0u ? 1u : 0u;
	if ( descriptor->cache_block_token_count > SPARK_MODEL_SERVING_ADAPTER_MAX_CACHE_BLOCK_TOKEN_COUNT ||
		(hybrid == 0u && descriptor->parallel_group_size != 0u) ||
		(hybrid != 0u && (descriptor->parallel_group_size < 2u ||
		 descriptor->parallel_group_size > descriptor->stage_count ||
		 descriptor->stage_count % descriptor->parallel_group_size != 0u)) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( descriptor->cache_block_token_count == 0u )
	{
		fprintf(stderr,"serving adapter: required cache_block_token_count is zero\n");
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	}
	if ( descriptor->cache_checkpoint_token_count % descriptor->cache_block_token_count != 0u )
	{
		fprintf(stderr,"serving adapter: cache_checkpoint_token_count %u is not a whole number of %u-token blocks\n",
			descriptor->cache_checkpoint_token_count,descriptor->cache_block_token_count);
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	}
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkDescriptorCheckIdentityFields(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	if ( SparkModelServingAdapterTextIsPresent(descriptor->adapter_id) == 0u || SparkModelServingAdapterTextIsPresent(descriptor->model_id) == 0u || SparkModelServingAdapterTextIsPresent(descriptor->model_revision) == 0u || SparkModelServingAdapterTextIsPresent(descriptor->driver_program_name) == 0u || SparkModelServingAdapterSha256IsValid(descriptor->artifact_sha256) == 0u )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkDescriptorCheckStageLayerTotals(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	uint32_t group,group_count,hybrid,index,parallel,total;
	hybrid = (descriptor->capability_flags &
		SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_HYBRID_TP_PP) != 0u ? 1u : 0u;
	parallel = (descriptor->capability_flags &
		SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_PARALLEL_FANOUT) != 0u ? 1u : 0u;
	total = 0u;
	for (index=0u; index<descriptor->stage_count; index++)
	{
		if ( descriptor->stage_layer_counts[index] == 0u )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( index + 1u < descriptor->stage_count && ((descriptor->boundary_sideband_kinds[index] != 0u) != (descriptor->boundary_sideband_bytes_per_sequence[index] != 0u)) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( index + 1u == descriptor->stage_count && (descriptor->boundary_sideband_kinds[index] != 0u || descriptor->boundary_sideband_bytes_per_sequence[index] != 0u) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		total += descriptor->stage_layer_counts[index];
	}
	for (; index<SPARK_MODEL_SERVING_ADAPTER_MAX_STAGE_COUNT; index++)
		if ( descriptor->stage_layer_counts[index] != 0u || descriptor->boundary_sideband_kinds[index] != 0u || descriptor->boundary_sideband_bytes_per_sequence[index] != 0u )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( hybrid != 0u )
	{
		group_count = descriptor->stage_count / descriptor->parallel_group_size;
		total = 0u;
		for (group=0u; group<group_count; group++)
		{
			uint32_t group_layer_count;
			group_layer_count = descriptor->stage_layer_counts[
				group * descriptor->parallel_group_size];
			for (index=1u; index<descriptor->parallel_group_size; index++)
				if ( descriptor->stage_layer_counts[
					group * descriptor->parallel_group_size + index] !=
					group_layer_count )
					SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
			total += group_layer_count;
		}
		return(total == descriptor->layer_count ? SPARK_STATUS_OK :
			SPARK_STATUS_INVALID_ARGUMENT);
	}
	if ( total == descriptor->layer_count )
		return(SPARK_STATUS_OK);
	if ( parallel != 0u )
	{
		for (index=0u; index<descriptor->stage_count; index++)
			if ( descriptor->stage_layer_counts[index] != descriptor->layer_count )
				SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		return(SPARK_STATUS_OK);
	}
	SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
}

static SparkStatus SparkDescriptorCheckRequiredCacheOperations(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	if ( (descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_PREFIX_REUSE) == 0u )
	{
		fprintf(stderr,"serving adapter %s refused: it does not restore cached prompt prefixes; prefix reuse is required (I23)\n",descriptor->adapter_id);
		SPARK_FAIL(SPARK_STATUS_UNSUPPORTED);
	}
	if ( (descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_CACHE_PUBLISH) == 0u )
	{
		fprintf(stderr,"serving adapter %s refused: it cannot serve publish-only frames, so decode checkpoints and the final partial block of a reply are never published; cache publication is required (I23)\n",descriptor->adapter_id);
		SPARK_FAIL(SPARK_STATUS_UNSUPPORTED);
	}
	return(SPARK_STATUS_OK);
}

static const SparkModelServingAdapterDescriptorCheck SPARK_MODEL_SERVING_ADAPTER_DESCRIPTOR_CHECKS[] = {
	SparkDescriptorCheckAbi,
	SparkDescriptorCheckCapabilityAndCountFields,
	SparkDescriptorCheckParallelTransportHybridPairing,
	SparkDescriptorCheckBoundaryAndCodecFields,
	SparkDescriptorCheckCapacityFields,
	SparkDescriptorCheckSpeculationPairing,
	SparkDescriptorCheckDecodeChainRequirements,
	SparkDescriptorCheckCacheBlockFields,
	SparkDescriptorCheckIdentityFields,
	SparkDescriptorCheckStageLayerTotals,
	SparkDescriptorCheckRequiredCacheOperations,
};

SparkStatus SparkModelServingAdapterValidateDescriptor(
	const SparkModelServingAdapterDescriptor *descriptor)
{
	uint32_t index;
	if ( descriptor == 0 )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	for (index=0u; index<sizeof(SPARK_MODEL_SERVING_ADAPTER_DESCRIPTOR_CHECKS)/sizeof(SPARK_MODEL_SERVING_ADAPTER_DESCRIPTOR_CHECKS[0]); index++)
	{
		SparkStatus status = SPARK_MODEL_SERVING_ADAPTER_DESCRIPTOR_CHECKS[index](descriptor);
		if ( status != SPARK_STATUS_OK )
			SPARK_RETURN(status);
	}
	return(SPARK_STATUS_OK);
}

SparkStatus SparkModelServingAdapterValidateRuntimeLimits(
	const SparkModelServingAdapterDescriptor *descriptor,
	const SparkModelServingRuntimeLimits *runtime_limits)
{
	SparkStatus status;
	uint32_t index;
	status = SparkModelServingAdapterValidateDescriptor(descriptor);
	if ( status != SPARK_STATUS_OK || runtime_limits == 0 )
		return(status != SPARK_STATUS_OK ? status : SPARK_STATUS_INVALID_ARGUMENT);
	if ( runtime_limits->abi_version != SPARK_MODEL_SERVING_ADAPTER_ABI_VERSION || runtime_limits->descriptor_bytes != SPARK_MODEL_SERVING_RUNTIME_LIMITS_BYTES )
		SPARK_FAIL(SPARK_STATUS_ABI_MISMATCH);
	if ( runtime_limits->max_inflight_submission_count == 0u || runtime_limits->max_inflight_submission_count > descriptor->max_inflight_submission_count || runtime_limits->max_active_sequence_count == 0u || runtime_limits->max_active_sequence_count > descriptor->max_active_sequence_count || runtime_limits->max_input_row_count < runtime_limits->max_active_sequence_count || runtime_limits->max_input_row_count > descriptor->max_input_row_count || runtime_limits->resident_sequence_capacity < runtime_limits->max_active_sequence_count || runtime_limits->resident_sequence_capacity > descriptor->max_resident_sequence_count )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( runtime_limits->kv_physical_page_capacity <
		 runtime_limits->max_active_sequence_count ||
		 runtime_limits->kv_logical_page_capacity <
		 runtime_limits->resident_sequence_capacity ||
		 runtime_limits->kv_physical_page_capacity >
		 runtime_limits->kv_logical_page_capacity )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	for (index=0u; index<4u; index++)
		if ( runtime_limits->reserved[index] != 0u )
			SPARK_FAIL(SPARK_STATUS_ABI_MISMATCH);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkModelServingAdapterMissingOperation(
	const SparkModelServingAdapterDescriptor *descriptor,
	const char *operation)
{
	fprintf(stderr,"serving adapter %s: missing required operation %s\n",descriptor->adapter_id,operation);
	SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
}

SparkStatus SparkModelServingAdapterValidateInterface(
	const SparkModelServingAdapterInterface *adapter_interface,
	uint32_t required_capability_flags)
{
	SparkStatus status;
	if ( adapter_interface == 0 || (required_capability_flags & ~SPARK_MODEL_SERVING_ADAPTER_KNOWN_CAPABILITIES) != 0u )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( adapter_interface->abi_version != SPARK_MODEL_SERVING_ADAPTER_ABI_VERSION || adapter_interface->interface_bytes != SPARK_MODEL_SERVING_ADAPTER_INTERFACE_BYTES )
		SPARK_FAIL(SPARK_STATUS_ABI_MISMATCH);
	status = SparkModelServingAdapterValidateDescriptor(adapter_interface->descriptor);
	if ( status != SPARK_STATUS_OK )
		SPARK_RETURN(status);
	if ( (adapter_interface->descriptor->capability_flags & required_capability_flags) != required_capability_flags )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
#define SPARK_REQUIRE_SERVING_OPERATION(member) \
	if ( adapter_interface->member == 0 ) \
		return(SparkModelServingAdapterMissingOperation(adapter_interface->descriptor,#member));
	SPARK_REQUIRE_SERVING_OPERATION(initialize)
	SPARK_REQUIRE_SERVING_OPERATION(destroy)
	SPARK_REQUIRE_SERVING_OPERATION(validate_submission)
	SPARK_REQUIRE_SERVING_OPERATION(submit)
	SPARK_REQUIRE_SERVING_OPERATION(prefetch)
	SPARK_REQUIRE_SERVING_OPERATION(resolve_prefetch)
	SPARK_REQUIRE_SERVING_OPERATION(progress)
	SPARK_REQUIRE_SERVING_OPERATION(quiesce)
	SPARK_REQUIRE_SERVING_OPERATION(snapshot)
	SPARK_REQUIRE_SERVING_OPERATION(reset)
#undef SPARK_REQUIRE_SERVING_OPERATION
	return(SPARK_STATUS_OK);
}

static uint32_t SparkModelServingAdapterLaneBlockIdentities(
	const SparkModelServingLane *lane,
	uint32_t cache_block_token_count,
	uint32_t verify)
{
	if ( cache_block_token_count == 0u || lane->context_token_count <= lane->sequence_position )
		return(0u);
	if ( verify != 0u && (lane->flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PUBLISH) == 0u )
		return(lane->context_token_count / cache_block_token_count - (uint32_t)(lane->sequence_position / cache_block_token_count));
	if ( (lane->flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PUBLISH) == 0u )
		return(0u);
	return((lane->context_token_count - 1u) / cache_block_token_count - (uint32_t)(lane->sequence_position / cache_block_token_count));
}

static SparkStatus SparkModelServingAdapterValidateRows(
	const SparkModelServingSubmission *submission,
	uint32_t require_live_rows,
	uint32_t resident_sequence_capacity,
	uint32_t cache_block_token_count)
{
	uint8_t seen[SPARK_MODEL_SERVING_ADAPTER_MAX_ACTIVE_SEQUENCE_COUNT];
	uint8_t seen_slots[SPARK_MODEL_SERVING_ADAPTER_MAX_RESIDENT_SEQUENCE_COUNT];
	uint32_t lane,row,slot,identities;
	uint32_t prefix_identity_present,publish_identity_present;
	identities = 0u;
	memset(seen,0,sizeof(seen));
	memset(seen_slots,0,sizeof(seen_slots));
	for (lane=0u; lane<submission->lane_count; lane++)
	{
		if ( (submission->lanes[lane].flags & ~SPARK_MODEL_SERVING_LANE_KNOWN_FLAGS) != 0u ||
			(submission->work_kind == SPARK_MODEL_SERVING_WORK_KIND_RELEASE && submission->lanes[lane].flags != 0u) ||
			(submission->work_kind == SPARK_MODEL_SERVING_WORK_KIND_DECODE && lane < submission->active_sequence_count && (submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_OUTPUT_TOKEN) == 0u) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( lane >= submission->active_sequence_count )
		{
			SparkModelServingCacheIdentity zero_identity;
			memset(&zero_identity,0,sizeof(zero_identity));
			if ( submission->lanes[lane].request_id != 0u || submission->lanes[lane].request_generation != 0u || submission->lanes[lane].step_generation != 0u || submission->lanes[lane].sequence_id != 0u || submission->lanes[lane].sequence_position != 0u || submission->lanes[lane].resident_sequence_slot != SPARK_MODEL_SERVING_NO_RESIDENT_SEQUENCE_SLOT || submission->lanes[lane].context_token_count != 0u || submission->lanes[lane].input_token_id != 0u || submission->lanes[lane].flags != 0u || submission->lanes[lane].cache_prefix_token_count != 0u || submission->lanes[lane].cache_publish_token_count != 0u || submission->lanes[lane].cache_block_identity_first != 0u || submission->lanes[lane].cache_block_identity_count != 0u || memcmp(&submission->lanes[lane].cache_prefix_identity,&zero_identity,sizeof(zero_identity)) != 0 || memcmp(&submission->lanes[lane].cache_publish_identity,&zero_identity,sizeof(zero_identity)) != 0 )
				SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
			continue;
		}
		slot = submission->lanes[lane].resident_sequence_slot;
		if ( submission->lanes[lane].request_id == 0u || submission->lanes[lane].request_generation == 0u || submission->lanes[lane].step_generation == 0u || submission->lanes[lane].sequence_id == 0u || slot >= resident_sequence_capacity || seen_slots[slot] != 0u )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		prefix_identity_present = 0u;
		publish_identity_present = 0u;
		for (row=0u; row<sizeof(submission->lanes[lane].cache_prefix_identity.sha256); row++)
			prefix_identity_present |= submission->lanes[lane].cache_prefix_identity.sha256[row];
		for (row=0u; row<sizeof(submission->lanes[lane].cache_publish_identity.sha256); row++)
			publish_identity_present |= submission->lanes[lane].cache_publish_identity.sha256[row];
		if ( ((submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PREFIX) != 0u) != (submission->lanes[lane].cache_prefix_token_count != 0u) || ((submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PREFIX) != 0u) != (prefix_identity_present != 0u) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( submission->lanes[lane].cache_prefix_token_count != 0u && (cache_block_token_count == 0u || submission->lanes[lane].cache_prefix_token_count > submission->lanes[lane].sequence_position) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( ((submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PUBLISH) != 0u) != (submission->lanes[lane].cache_publish_token_count != 0u) || ((submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PUBLISH) != 0u) != (publish_identity_present != 0u) ||
			((submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_STATELESS) != 0u && (submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PUBLISH) == 0u) ||
			((submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_STAGED) != 0u && (submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_STATELESS) == 0u) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( submission->lanes[lane].cache_publish_token_count != 0u && (cache_block_token_count == 0u || submission->lanes[lane].cache_publish_token_count <= submission->lanes[lane].cache_prefix_token_count || submission->lanes[lane].cache_publish_token_count > submission->lanes[lane].context_token_count) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( submission->work_kind == SPARK_MODEL_SERVING_WORK_KIND_CACHE_PUBLISH &&
			((submission->lanes[lane].flags & ~(SPARK_MODEL_SERVING_LANE_FLAG_CACHE_STATELESS | SPARK_MODEL_SERVING_LANE_FLAG_CACHE_STAGED)) != SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PUBLISH ||
			 submission->lanes[lane].cache_publish_token_count != submission->lanes[lane].context_token_count ||
			 submission->lanes[lane].sequence_position != submission->lanes[lane].context_token_count) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( submission->lanes[lane].cache_block_identity_first != identities ||
			submission->lanes[lane].cache_block_identity_count != SparkModelServingAdapterLaneBlockIdentities(&submission->lanes[lane],cache_block_token_count,
				(submission->flags & SPARK_MODEL_SERVING_SUBMISSION_FLAG_VERIFY) != 0u ? 1u : 0u) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		identities += submission->lanes[lane].cache_block_identity_count;
		seen_slots[slot] = 1u;
	}
	if ( identities != submission->cache_block_identity_count || (identities != 0u) != (submission->cache_block_identities != 0) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	for (row=0u; row<submission->row_count; row++)
	{
		lane = submission->row_lane_indices[row];
		if ( lane >= submission->active_sequence_count || submission->row_sequence_ids[row] != submission->lanes[lane].sequence_id )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		seen[lane] = 1u;
	}
	for (lane=0u; require_live_rows != 0u && lane<submission->active_sequence_count; lane++)
		if ( seen[lane] == 0u )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkModelServingAdapterFindLastRows(
	const SparkModelServingSubmission *submission,
	uint32_t *last_rows)
{
	uint8_t seen[SPARK_MODEL_SERVING_ADAPTER_MAX_ACTIVE_SEQUENCE_COUNT];
	uint64_t last_positions[SPARK_MODEL_SERVING_ADAPTER_MAX_ACTIVE_SEQUENCE_COUNT];
	uint32_t lane,row;
	if ( submission == 0 || last_rows == 0 || submission->abi_version != SPARK_MODEL_SERVING_ADAPTER_ABI_VERSION || submission->descriptor_bytes != SPARK_MODEL_SERVING_SUBMISSION_BYTES || (submission->work_kind != SPARK_MODEL_SERVING_WORK_KIND_PREFILL && submission->work_kind != SPARK_MODEL_SERVING_WORK_KIND_DECODE) || submission->active_sequence_count == 0u || submission->active_sequence_count > SPARK_MODEL_SERVING_ADAPTER_MAX_ACTIVE_SEQUENCE_COUNT || submission->lane_count < submission->active_sequence_count || submission->lane_count > SPARK_MODEL_SERVING_ADAPTER_MAX_ACTIVE_SEQUENCE_COUNT || submission->row_count < submission->active_sequence_count || submission->row_count > SPARK_MODEL_SERVING_ADAPTER_MAX_INPUT_ROW_COUNT || submission->lanes == 0 || submission->row_lane_indices == 0 || submission->row_positions == 0 || submission->row_sequence_ids == 0 )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	memset(seen,0,sizeof(seen));
	for (lane=0u; lane<submission->lane_count; lane++)
	{
		if ( (submission->lanes[lane].flags & ~SPARK_MODEL_SERVING_LANE_KNOWN_FLAGS) != 0u ||
			(lane >= submission->active_sequence_count && submission->lanes[lane].flags != 0u) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( lane >= submission->active_sequence_count )
			continue;
		if ( submission->lanes[lane].sequence_id == 0u || submission->lanes[lane].context_token_count == 0u )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		last_rows[lane] = UINT32_MAX;
	}
	for (row=0u; row<submission->row_count; row++)
	{
		lane = submission->row_lane_indices[row];
		if ( lane >= submission->active_sequence_count || submission->row_sequence_ids[row] != submission->lanes[lane].sequence_id )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( seen[lane] == 0u && submission->row_positions[row] != submission->lanes[lane].sequence_position )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( seen[lane] != 0u && (last_positions[lane] == UINT64_MAX || submission->row_positions[row] != last_positions[lane] + 1u) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		seen[lane] = 1u;
		last_positions[lane] = submission->row_positions[row];
		last_rows[lane] = row;
	}
	for (lane=0u; lane<submission->active_sequence_count; lane++)
		if ( seen[lane] == 0u || last_positions[lane] == UINT64_MAX || last_positions[lane] + 1u != submission->lanes[lane].context_token_count )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

SparkStatus SparkModelServingAdapterSelectEmitRows(
	const SparkModelServingSubmission *submission,
	uint32_t *emit_row_indices,
	uint32_t *emit_lane_indices,
	uint32_t emit_capacity,
	uint32_t *emit_count_out)
{
	uint32_t last_rows[SPARK_MODEL_SERVING_ADAPTER_MAX_ACTIVE_SEQUENCE_COUNT];
	uint32_t count,lane,row;
	SparkStatus status;
	if ( emit_count_out == 0 || ((emit_row_indices == 0) != (emit_lane_indices == 0)) || (emit_row_indices == 0 && emit_capacity != 0u) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	*emit_count_out = 0u;
	status = SparkModelServingAdapterFindLastRows(submission,last_rows);
	if ( status != SPARK_STATUS_OK )
		SPARK_RETURN(status);
	count = 0u;
	for (lane=0u; lane<submission->active_sequence_count; lane++)
		count += (submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_OUTPUT_TOKEN) != 0u ? 1u : 0u;
	if ( emit_row_indices != 0 && count > emit_capacity )
		SPARK_FAIL(SPARK_STATUS_CAPACITY_EXCEEDED);
	if ( emit_row_indices != 0 )
	{
		count = 0u;
		for (row=0u; row<submission->row_count; row++)
		{
			lane = submission->row_lane_indices[row];
			if ( last_rows[lane] == row && (submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_OUTPUT_TOKEN) != 0u )
			{
				emit_row_indices[count] = row;
				emit_lane_indices[count] = lane;
				count++;
			}
		}
	}
	*emit_count_out = count;
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkModelServingAdapterValidateSampling(
	const SparkModelServingAdapterDescriptor *descriptor,
	const SparkModelServingSubmission *submission)
{
	const SparkRowSampling *rule;
	uint32_t lane,stride = 0u;
	for (lane=0u; lane<submission->lane_count; lane++)
	{
		rule = &submission->lanes[lane].sampling;
		if ( SparkSamplingRuleValid(rule) == 0u )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( SparkSamplingRuleNeedsDistribution(rule) != 0u && (lane >= submission->active_sequence_count || SparkModelServingWorkKindUsesRows(submission->work_kind) == 0u) )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		if ( rule->inverse_temperature != 0.0f && (descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_SAMPLING) == 0u )
			SPARK_FAIL(SPARK_STATUS_UNSUPPORTED);
		if ( SparkSamplingRuleTruncates(rule) != 0u && (descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_SAMPLING_TRUNCATION) == 0u )
			SPARK_FAIL(SPARK_STATUS_UNSUPPORTED);
		if ( rule->logprobs != 0u && (descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_LOGPROBS) == 0u )
			SPARK_FAIL(SPARK_STATUS_UNSUPPORTED);
		stride = rule->logprobs > stride ? rule->logprobs : stride;
	}
	if ( stride != 0u && (uint64_t)submission->active_sequence_count * (submission->tokens_per_sequence > 1u ? submission->tokens_per_sequence : 1u) * stride > SPARK_MODEL_SERVING_ADAPTER_MAX_LOGPROB_ENTRIES )
		SPARK_FAIL(SPARK_STATUS_CAPACITY_EXCEEDED);
	return(SPARK_STATUS_OK);
}

static SparkStatus SparkModelServingAdapterValidateVerifyRows(
	const SparkModelServingSubmission *submission)
{
	uint32_t counts[SPARK_MODEL_SERVING_ADAPTER_MAX_ACTIVE_SEQUENCE_COUNT];
	uint32_t lane,row;
	memset(counts,0,sizeof(counts));
	for (lane=0u; lane<submission->active_sequence_count && lane<submission->row_count; lane++)
		if ( submission->row_lane_indices[lane] != lane )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	for (row=0u; row<submission->row_count; row++)
	{
		lane = submission->row_lane_indices[row];
		if ( lane >= submission->active_sequence_count || counts[lane] >= submission->tokens_per_sequence ||
			submission->row_positions[row] != submission->lanes[lane].sequence_position + counts[lane] ||
			(counts[lane] == 0u && submission->token_ids[row] != submission->lanes[lane].input_token_id) ||
			submission->token_ids[row] == SPARK_MODEL_SERVING_NO_TOKEN )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		counts[lane]++;
	}
	for (lane=0u; lane<submission->active_sequence_count; lane++)
		if ( counts[lane] == 0u || submission->lanes[lane].context_token_count != submission->lanes[lane].sequence_position + counts[lane] ||
			(submission->lanes[lane].flags & SPARK_MODEL_SERVING_LANE_FLAG_CACHE_PUBLISH) != 0u )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	return(SPARK_STATUS_OK);
}

SparkStatus SparkModelServingAdapterValidateSubmission(
	const SparkModelServingAdapterDescriptor *descriptor,
	const SparkModelServingSubmission *submission)
{
	uint32_t verify;
	SparkStatus status;
	uint32_t total_output_tokens;
	status = SparkModelServingAdapterValidateDescriptor(descriptor);
	if ( status != SPARK_STATUS_OK )
		SPARK_RETURN(status);
	if ( submission == 0 )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( submission->abi_version != SPARK_MODEL_SERVING_ADAPTER_ABI_VERSION || submission->descriptor_bytes != SPARK_MODEL_SERVING_SUBMISSION_BYTES )
		SPARK_FAIL(SPARK_STATUS_ABI_MISMATCH);
	if ( (submission->flags & ~SPARK_MODEL_SERVING_SUBMISSION_KNOWN_FLAGS) != 0u || submission->submission_id == 0u || submission->control_generation == 0u || submission->transaction_id == 0u || submission->dispatch_generation == 0u || submission->request_generation == 0u || submission->step_generation == 0u || submission->work_kind < SPARK_MODEL_SERVING_WORK_KIND_PREFILL || submission->work_kind > SPARK_MODEL_SERVING_WORK_KIND_CACHE_PUBLISH || submission->lane_count == 0u || submission->lane_count > descriptor->max_active_sequence_count || submission->active_sequence_count == 0u || submission->active_sequence_count > submission->lane_count || submission->lanes == 0 )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( submission->work_kind == SPARK_MODEL_SERVING_WORK_KIND_CACHE_PUBLISH &&
		(descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_CACHE_PUBLISH) == 0u )
		SPARK_FAIL(SPARK_STATUS_UNSUPPORTED);
	verify = (submission->flags & SPARK_MODEL_SERVING_SUBMISSION_FLAG_VERIFY) != 0u ? 1u : 0u;
	if ( verify != 0u && submission->work_kind != SPARK_MODEL_SERVING_WORK_KIND_DECODE )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( verify != 0u && ((descriptor->capability_flags & SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_SPECULATIVE_VERIFY) == 0u ||
		submission->tokens_per_sequence > descriptor->max_speculative_token_count + 1u) )
		SPARK_FAIL(SPARK_STATUS_UNSUPPORTED);
	if ( verify != 0u && submission->row_count > descriptor->max_verify_row_count )
		SPARK_FAIL(SPARK_STATUS_CAPACITY_EXCEEDED);
	if ( submission->model_extension_bytes > SPARK_MODEL_SERVING_ADAPTER_MAX_EXTENSION_BYTES || (submission->model_extension_bytes != 0u) != (submission->model_extension != 0) || (submission->model_extension_bytes != 0u) != (submission->model_extension_kind != 0u) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	status = SparkModelServingAdapterValidateSampling(descriptor,submission);
	if ( status != SPARK_STATUS_OK )
		SPARK_RETURN(status);
	if ( SparkModelServingWorkKindUsesRows(submission->work_kind) == 0u )
	{
		if ( submission->tokens_per_sequence != 0u )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	}
	else if ( submission->tokens_per_sequence == 0u ||
		submission->tokens_per_sequence > (verify != 0u ?
		SPARK_MODEL_SERVING_ADAPTER_MAX_VERIFY_TOKENS_PER_SEQUENCE :
		SPARK_MODEL_SERVING_ADAPTER_MAX_TOKENS_PER_SEQUENCE) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	else if ( submission->work_kind == SPARK_MODEL_SERVING_WORK_KIND_PREFILL &&
		submission->tokens_per_sequence != 1u )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	else if ( verify == 0u && submission->tokens_per_sequence > 1u &&
		(descriptor->capability_flags &
		 SPARK_MODEL_SERVING_ADAPTER_CAPABILITY_RESIDENT_DECODE_CHAIN) == 0u )
		SPARK_FAIL(SPARK_STATUS_UNSUPPORTED);
	total_output_tokens = 0u;
	if ( submission->tokens_per_sequence != 0u )
		total_output_tokens = submission->active_sequence_count <= UINT32_MAX /
			submission->tokens_per_sequence ? submission->active_sequence_count *
			submission->tokens_per_sequence : UINT32_MAX;
	if ( total_output_tokens > (verify != 0u ? SparkModelServingAdapterCompletionTokenCapacity(descriptor) : descriptor->max_output_token_count) )
		SPARK_FAIL(SPARK_STATUS_CAPACITY_EXCEEDED);
	if ( (submission->hidden_input_address != 0) != (submission->hidden_input_bytes != 0u) || (submission->boundary_sideband_input_address != 0) != (submission->boundary_sideband_input_bytes != 0u) || (submission->hidden_output_address != 0) != (submission->hidden_output_bytes != 0u) || (submission->boundary_sideband_output_address != 0) != (submission->boundary_sideband_output_bytes != 0u) )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( SparkModelServingWorkKindUsesRows(submission->work_kind) == 0u )
	{
		if ( submission->row_count != 0u || submission->token_count != 0u || submission->new_token_count != 0u || submission->hidden_input_address != 0 || submission->boundary_sideband_input_address != 0 || submission->hidden_output_address != 0 || submission->boundary_sideband_output_address != 0 )
			SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
		return(SparkModelServingAdapterValidateRows(submission,0u,descriptor->max_resident_sequence_count,descriptor->cache_block_token_count));
	}
	if ( submission->row_count == 0u || submission->token_count != submission->row_count || submission->new_token_count != submission->row_count || submission->token_count > descriptor->max_input_row_count || submission->token_ids == 0 || submission->row_lane_indices == 0 || submission->row_positions == 0 || submission->row_sequence_ids == 0 )
		SPARK_FAIL(SPARK_STATUS_INVALID_ARGUMENT);
	if ( verify != 0u )
	{
		status = SparkModelServingAdapterValidateVerifyRows(submission);
		if ( status != SPARK_STATUS_OK )
			SPARK_RETURN(status);
	}
	return(SparkModelServingAdapterValidateRows(submission,1u,descriptor->max_resident_sequence_count,descriptor->cache_block_token_count));
}

SparkStatus SparkModelServingAdapterValidateRuntimeSubmission(
