static SparkStatus StageServingEnvU64(const char *name, uint64_t *value)
{
	const char *text = getenv(name);
	char *end = 0;
	if ( text == 0 || *text == '\0' )
		return SPARK_STATUS_INVALID_ARGUMENT;
	errno = 0;
